        if weight > max_parcel_grams:
            raise ValueError("unit weight exceeds max_parcel_grams")
        if sku in sku_weights and sku_weights[sku] != weight:
            raise ValueError("inconsistent weights")
        sku_weights[sku] = weight

    items_to_pack = []
    for sku, qty, weight in lines:
        line_total_weight = qty * weight
        if line_total_weight <= max_parcel_grams:
            # Pack the whole line as one item
            items_to_pack.append((sku, line_total_weight, qty))
        else:
